static func card_reward_score(d: Dictionary, aspect: int, card_id: String,
		deck: Array = []) -> float:
	var score: float = card_score(d, aspect, card_id)
	var partner: String = {
		"chisel": "executioner", "executioner": "chisel",
		"defend": "guardedStrike", "guardedStrike": "defend",
		"toxicMist": "catalyst", "catalyst": "toxicMist",
		"bloodRite": "leechBlade", "leechBlade": "bloodRite",
	}.get(card_id, "")
	var applicable: bool = (aspect == 0 and card_id in ["chisel", "executioner", "defend",
		"guardedStrike"]) or (aspect == 1 and card_id in ["toxicMist", "catalyst",
		"bloodRite", "leechBlade"])
	if applicable and not partner.is_empty():
		for card: CardInst in deck:
			if String(card.id) == partner:
				return score + _research421("acquisitionPriority") \
					* _w("card", "aspectBonus")
	return score

