static func _harvest_fight(game: GlassvowGame, fight_index: int) -> void:
	var relics: Array[String] = game.run.player.relics
	if relics.has("ashenCore"):
		_bump("ashenCoreOwned")
	if relics.has("smolderingCoal"):
		_bump("smolderingCoalOwned")
	if relics.has("hollowCrown"):
		_bump("hollowCrownOwned")
	var last_play: String = ""
	var event_index: int = 0
	for event_v: Variant in game.cb.queue:
		var event: Dictionary = event_v
		var kind: String = str(event.get("t", ""))
		if kind == "turn":
			last_play = ""
			if relics.has("hollowCrown"):
				var gain: int = _ji(game.content.relic(&"hollowCrown").get("energyGain", 1))
				if gain > 0:
					_bump("extraEnergyGrantedByCrown", gain)
		elif kind == "draw":
			var drawn: String = str(event.get("id", ""))
			_bump("%sDrawn" % drawn)
			if last_play in ["quickSlash", "sidestep", "preparation"]:
				_bump("cardsDrawnByCycle")
			elif last_play == "deflect":
				_bump("cardsDrawnByDeflect")
		elif kind == "play":
			last_play = str(event.get("id", ""))
			_trace_append("plays", {"fight": fight_index, "event": event_index,
				"id": last_play})
			_bump("%sPlayed" % last_play)
		elif kind == "hitEnemy" and last_play in ["phantomBlades", "guardedStrike", "leechBlade"]:
			var metric: String = "phantomDamage" if last_play == "phantomBlades" \
				else ("afterimageGuardDamage" if last_play == "guardedStrike" \
				else "bloodfireLeechDamage")
			_bump(metric, maxi(0, _ji(event.get("amount", 0))))
		elif kind == "status":
			var status_id: String = str(event.get("id", ""))
			var status_n: int = _ji(event.get("n", 0))
			if last_play == "eclipseSlash" and status_id == "vulnerable":
				_bump("crackedAppliedByEclipseSlash")
			elif last_play in ["ashBite", "smother"] and status_id == "poison":
				_bump("smolderAppliedByStarters")
			elif last_play == "toxicMist" and status_id == "poison":
				_bump("smolderAppliedByToxicMist")
			elif last_play == "ashenChoir" and status_id == "poison":
				_bump("smolderAppliedByStack")
			elif last_play == "catalyst" and status_id == "poison" and status_n > 0:
				_bump("smolderAmplifiedByCatalyst", status_n)
			elif last_play == "toxicMist" and status_id == "mistbound" and status_n > 0:
				_bump("mistboundAppliedByToxicMist", status_n)
			elif last_play == "catalyst" and status_id == "mistbound" and status_n < 0:
				_bump("mistboundConsumedByCatalyst", -status_n)
			elif last_play == "chisel" and status_id == "scoreline" and status_n > 0:
				_bump("scorelineApplied", status_n)
			elif last_play == "executioner" and status_id == "scoreline" and status_n < 0:
				_bump("scorelineConsumed", -status_n)
			elif last_play == "defend" and status_id == "afterimage" and status_n > 0:
				_bump("afterimageApplied", status_n)
			elif last_play == "guardedStrike" and status_id == "afterimage" and status_n < 0:
				_bump("afterimageConsumed", -status_n)
			elif last_play == "bloodRite" and status_id == "bloodfire" and status_n > 0:
				_bump("bloodfireApplied", status_n)
			elif last_play == "leechBlade" and status_id == "bloodfire" and status_n < 0:
				_bump("bloodfireConsumed", -status_n)
		elif kind == "heal" and last_play == "leechBlade":
			_bump("bloodfireLeechHeal", maxi(0, _ji(event.get("n", 0))))
		elif kind == "blockGain" and str(event.get("who", "")) == "player":
			if last_play == "smother":
				_bump("wardGainedBySmother")
			elif last_play == "deflect":
				_bump("wardGainedByDeflect")
			elif last_play in ["brace", "bulwark"]:
				_bump("%sWardGained" % last_play, _ji(event.get("n", 0)))
			elif last_play == "fortify":
				_bump("wardDoubledByFortify", _ji(event.get("n", 0)))
			elif last_play == "guardedStrike":
				_bump("afterimageGuardWard", _ji(event.get("n", 0)))
		elif kind == "relicProc":
			var relic_id: String = str(event.get("id", ""))
			if relic_id == "ashenCore":
				_bump("ashenCoreTriggered")
			elif relic_id == "smolderingCoal":
				_bump("smolderingCoalTriggered")
		event_index += 1

